int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();
    vector<int> d(n, 0);
    int l = 0, rr = -1;
    for (int i = 0; i < n; i++) {
        int k = (i > rr) ? 1 : min(d[l + rr - i], rr - i + 1);
        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) k++;
        d[i] = k;
        if (i + k - 1 > rr) {
            l = i - k + 1;
            rr = i + k - 1;
        }
    }
    for (int i = 0; i < n; i++) cout << (i ? " " : "") << 2 * d[i] - 1;
    cout << "\n";

    return 0;
}

